/**
 * Invoicing module: line items, tax, discounts and totals.
 *
 * All monetary values are integer minor units (e.g. cents) so that sums
 * never accumulate floating-point error.
 */

/** A single billable line on an invoice. */
export interface LineItem {
  /** Human-readable description shown on the invoice. */
  description: string;
  /** Price of one unit, in minor units. */
  unitPrice: number;
  /** Number of units; must be a positive integer. */
  quantity: number;
  /** Tax rate for this line as a fraction (0.2 = 20%). Defaults to the invoice rate. */
  taxRate?: number;
}

/** A discount applied to the invoice subtotal. */
export type Discount =
  | { kind: "percent"; /** Fraction of the subtotal, 0..1. */ value: number }
  | { kind: "fixed"; /** Amount in minor units. */ value: number };

/** An invoice before totals are computed. */
export interface Invoice {
  /** Unique invoice identifier. */
  id: string;
  /** Lines being billed. */
  items: LineItem[];
  /** Optional discounts, applied in order to the subtotal. */
  discounts?: Discount[];
  /** Default tax rate for lines without their own rate. */
  defaultTaxRate?: number;
}

/** The computed monetary breakdown of an invoice. */
export interface InvoiceTotals {
  /** Sum of all line amounts before discounts and tax. */
  subtotal: number;
  /** Total amount removed by discounts. */
  discountTotal: number;
  /** Tax charged on the discounted amount. */
  tax: number;
  /** Final amount due: subtotal - discountTotal + tax. */
  total: number;
}

/**
 * Computes the net amount of a line item (unit price times quantity).
 *
 * @throws RangeError if the quantity is not a positive integer or the price is negative.
 */
export function lineAmount(item: LineItem): number {
  if (!Number.isInteger(item.quantity) || item.quantity <= 0) {
    throw new RangeError(`quantity must be a positive integer: ${item.description}`);
  }
  if (!Number.isInteger(item.unitPrice) || item.unitPrice < 0) {
    throw new RangeError(`unitPrice must be a non-negative integer: ${item.description}`);
  }
  return item.unitPrice * item.quantity;
}

/** Sums the net amounts of all line items. */
export function subtotal(items: LineItem[]): number {
  return items.reduce((sum, item) => sum + lineAmount(item), 0);
}

/**
 * Applies discounts in order and returns the total amount discounted.
 * The result is capped at the subtotal, so an invoice never goes negative.
 *
 * @throws RangeError if a discount value is out of range.
 */
export function discountTotal(base: number, discounts: Discount[] = []): number {
  let remaining = base;
  for (const d of discounts) {
    if (d.value < 0 || (d.kind === "percent" && d.value > 1)) {
      throw new RangeError(`invalid ${d.kind} discount: ${d.value}`);
    }
    const amount = d.kind === "percent" ? Math.round(remaining * d.value) : d.value;
    remaining -= Math.min(amount, remaining);
  }
  return base - remaining;
}

/**
 * Computes tax over the discounted invoice. Discounts are spread across lines
 * proportionally to each line's share of the subtotal, then each line is taxed
 * at its own rate and rounded to the nearest minor unit.
 */
export function taxTotal(
  items: LineItem[],
  discount: number,
  defaultTaxRate = 0,
): number {
  const base = subtotal(items);
  if (base === 0) return 0;
  let tax = 0;
  for (const item of items) {
    const rate = item.taxRate ?? defaultTaxRate;
    if (rate < 0) throw new RangeError(`taxRate must be non-negative: ${item.description}`);
    const share = lineAmount(item) / base;
    const taxable = lineAmount(item) - discount * share;
    tax += Math.round(taxable * rate);
  }
  return tax;
}

/** Computes the full breakdown (subtotal, discounts, tax, total) for an invoice. */
export function computeTotals(invoice: Invoice): InvoiceTotals {
  const sub = subtotal(invoice.items);
  const discount = discountTotal(sub, invoice.discounts);
  const tax = taxTotal(invoice.items, discount, invoice.defaultTaxRate);
  return { subtotal: sub, discountTotal: discount, tax, total: sub - discount + tax };
}

/** Formats minor units as a fixed two-decimal string, e.g. 1999 -> "19.99". */
export function formatAmount(minor: number): string {
  const sign = minor < 0 ? "-" : "";
  const abs = Math.abs(minor);
  return `${sign}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, "0")}`;
}
